#!/usr/bin/env node
/**
 * Copies the logo's vector paths from the website into the app:
 *
 *   node scripts/brand-paths.js
 *
 * Reads  frontend/src/app/components/brand/markPath.js and wordmarkPath.js
 *        (themselves generated by frontend/scripts/brandLogo.js)
 * Writes src/ui/brandPaths.ts
 *
 * The app is its own package and cannot import the website's modules, so it
 * keeps a COPY — and a copy is what drifts. test/brand.test.ts reads both files
 * and fails when they disagree, which is the cue to re-run this. Never edit
 * brandPaths.ts by hand.
 */
const fs = require('node:fs');
const path = require('node:path');

const BRAND = path.join(__dirname, '..', '..', 'frontend', 'src', 'app', 'components', 'brand');
const OUT = path.join(__dirname, '..', 'src', 'ui', 'brandPaths.ts');

const NAMES = {
  'markPath.js': ['MARK_VIEWBOX', 'MARK_FRAME', 'MARK_INITIAL'],
  'wordmarkPath.js': ['WORDMARK_VIEWBOX', 'LOGO_GAP', 'WORDMARK_EVENTS', 'WORDMARK_LI', 'WORDMARK_SPARK'],
};

function read(file, name) {
  const src = fs.readFileSync(path.join(BRAND, file), 'utf8');
  const m = src.match(new RegExp(`export const ${name} = '([^']+)';`));
  if (!m) throw new Error(`brand-paths: no ${name} in ${file}`);
  return m[1];
}

let out = `/**
 * The logo's paths, copied from the website by scripts/brand-paths.js.
 * GENERATED — do not edit. test/brand.test.ts fails if this drifts from
 * frontend/src/app/components/brand/.
 */
`;
for (const [file, names] of Object.entries(NAMES)) {
  for (const name of names) out += `export const ${name} = '${read(file, name)}';\n`;
}
fs.writeFileSync(OUT, out);
console.log(`Wrote ${OUT}`);

module.exports = { read, NAMES };
